mapper.select:

WHERE a.ASGN_STAT_CD='ACT'
AND a.INPUT_END_DT BETWEEN make_date(#{year},1,1) AND make_date(#{year},12,31)
AND a.INPUT_END_DT >= #{from}
AND a.INPUT_END_DT <= #{through}
AND a.JOB_CD=#{jobCode}

  AND a.EXT_PSBL_CD IS NULL
    AND a.EXT_PSBL_CD=#{extensionPossibilityCode}

ORDER BY a.INPUT_END_DT,a.ASGN_ID

WHERE a.ASGN_STAT_CD='ACT' AND a.DEV_ID=#{developerId}
AND EXISTS(SELECT 1 FROM TB_SL_TENT_ASGN t WHERE t.DEV_ID=a.DEV_ID AND t.OPP_ID=#{opportunityId} AND t.TENT_STAT_CD IN ('ACT','CNVT'))
ORDER BY a.INPUT_END_DT,a.ASGN_ID

mapper.update:
UPDATE TB_SL_TENT_ASGN SET TENT_STAT_CD='REL',PROC_DTTM=clock_timestamp(),
  MOD_DTTM=clock_timestamp(),MOD_USER_ID=#{actor}
WHERE TENT_ID=CAST(#{id} AS numeric) AND TENT_STAT_CD='ACT'

mapper.select:
SELECT n.NEED_CNT AS "requiredCount",n.MON_MM AS "monthlyMm",o.WIN_PRBL_RT AS "winningProbability"
FROM TB_SL_OPP_NEED n JOIN TB_SL_OPP o ON o.OPP_ID=n.OPP_ID
WHERE o.OPP_STAT_CD='ING' AND n.JOB_CD=#{jobCode}
  AND to_date(n.BGN_YM,'YYYYMM') <= #{firstDay}
  AND to_date(n.BGN_YM,'YYYYMM')+make_interval(months => n.PRD_MCNT::int) > #{firstDay}
ORDER BY n.OPP_ID,n.NEED_SN
